/* ================================================================ PUDDING HOP (runner + ghosts) */
// Two rule versions live side by side. A payload without `v` is v1: the gentle original, FROZEN below so every run
// already in the chat keeps replaying to the score it was sent with. New runs are v2 (games/hop-rules.js, inlined
// above this file's main block as window.HOP_RULES): integer physics, phases, x2 gravity, 90 s "film". Never edit
// v1; a future rules change is v3 with its own seed salt, and v2 stays reachable the same way.
const HR=window.HOP_RULES;
/* ---- v1 (frozen: replay only) */
const HOP={W:320,H:150,G:128,PX:46,DT:1/60,MAXF:60*180};
const SPD=d=>Math.min(400,150+d*.0105);
const COURSES=new Map();
// the course is a pure function of the seed: every phone builds the same obstacles in the same places
function getCourse(seed){if(COURSES.has(seed))return COURSES.get(seed);const R=mulberry32(seed),obs=[];let x=620;
 const c={obs,ensure(d){while(x<d+HOP.W+120){const v=SPD(x),r=R();let k;
   if(x>3200&&r<.13)k='double';else if(x>1700&&r<.33)k='tall';else k=['bucket','reel','clap'][(R()*3)|0];
   const o=k==='bucket'?{w:14,h:18}:k==='tall'?{w:15,h:26}:k==='reel'?{w:17,h:17}:k==='clap'?{w:22,h:15}:{w:38,h:18};
   o.k=k;o.x=x;o.id=obs.length+1;obs.push(o);x+=o.w+v*.6+38+R()*v*.9}}};
 COURSES.set(seed,c);return c}
function hopRun(seed,frames){return{seed,course:getCourse(seed),f:0,d:0,y:0,vy:0,ground:true,prevHeld:false,holdT:0,landT:0,dead:false,score:0,frames:frames||null,ip:0}}
// a recorded run = [press, release, press, release…] in simulation frames; held means press <= f < release
function ghostHeld(r){const a=r.frames;if(!a)return false;while(r.ip<a.length&&(a[r.ip+1]??Infinity)<=r.f)r.ip+=2;return r.ip<a.length&&a[r.ip]<=r.f}
function hopStep(s,held){if(s.dead)return;const dt=HOP.DT,v=SPD(s.d);s.d+=v*dt;s.course.ensure(s.d);
 if(held&&!s.prevHeld&&s.ground){s.vy=-330;s.ground=false;s.holdT=0}
 s.prevHeld=held;
 if(!s.ground){const lift=held&&s.vy<0&&s.holdT<.22;if(held)s.holdT+=dt;s.vy+=(lift?700:1900)*dt;s.y+=s.vy*dt;if(s.y>=0){s.y=0;s.vy=0;s.ground=true;s.landT=.16}}
 else if(s.landT>0)s.landT-=dt;
 const x0=s.d+HOP.PX-9,x1=s.d+HOP.PX+9,bot=HOP.G+s.y;
 for(const o of s.course.obs){if(o.x>x1)break;if(o.x+o.w<x0)continue;
  if(bot>HOP.G-o.h+3&&x1>o.x+3&&x0<o.x+o.w-3){s.dead=true;break}}
 s.f++;s.score=Math.floor(s.d/25);if(s.f>=HOP.MAXF)s.dead=true}
function drawObs(p,o,sx){const G=HOP.G;
 if(o.k==='reel'){const r=o.h/2,cx=sx+o.w/2,cy=G-r;p.shape(ell(cx,cy,r,r,16),'#fff','#111',1.4,.7);const a0=o.x*.05;
  for(let i=0;i<5;i++){const a=a0+i*1.2566;p.ring(cx+Math.cos(a)*r*.55,cy+Math.sin(a)*r*.55,r*.2,'#111',1,.3,8)}p.dot(cx,cy,1.1,'#111');return}
 if(o.k==='clap'){p.shape([[sx,G-10],[sx+o.w,G-10],[sx+o.w,G],[sx,G]],'#fff','#111',1.4,.6);
  p.shape([[sx,G-11],[sx+o.w,G-15],[sx+o.w+1,G-12],[sx+1,G-8]],'#fff','#111',1.2,.5);for(const f of [.25,.55,.85])p.line([[sx+o.w*f,G-10.5-f*3],[sx+o.w*f+3,G-9-f*3]],'#e0302a',2,.3);return}
 const one=(x,w,h)=>{const P=[[x,G-h],[x+w,G-h],[x+w-3,G],[x+3,G]];p.shape(P,'#fff','#111',1.4,.6);
  for(const f of [.3,.5,.7])p.line([[x+w*f,G-h+2],[x+w*f+(f-.5)*2,G-1]],'#e0302a',1.8,.3);p.shape(P,null,'#111',1.3,.5);
  for(const [dx,dy,r] of [[.25,-1,2.6],[.55,-3,3],[.8,-1,2.4]])p.shape(ell(x+w*dx,G-h+dy,r,r,8),'#fff','#111',1,.4)};
 if(o.k==='double'){one(sx,18,18);one(sx+20,18,18)}else one(sx,o.w,o.h)}

/* ================================================================ BILJART (turn-based 8-ball) */
const PT={x0:18,y0:18,x1:182,y1:338,r:6,W:200,H:356};
const POCKETS=[[18,18],[182,18],[16,178],[184,178],[18,338],[182,338]];
const BALLCOL={0:'#ffffff',1:'#ffd400',2:'#1f6fe0',3:'#e0302a',4:'#8a3ffc',5:'#ff8c1a',6:'#2fa84f',7:'#8b5a2b',8:'#111111'};for(let i=9;i<16;i++)BALLCOL[i]=BALLCOL[i-8];
const SPRITES={};function sprite(id){if(SPRITES[id])return SPRITES[id];const S=13,c=document.createElement('canvas');c.width=c.height=S;const x=c.getContext('2d'),im=x.createImageData(S,S),d=im.data,col=RGB(BALLCOL[id]);
 for(let j=0;j<S;j++)for(let i=0;i<S;i++){const dx=i-6,dy=j-6,r=Math.hypot(dx,dy),k=(j*S+i)*4;if(r>6.4)continue;let o;
  if(r>5.3)o=[17,17,17];else if(id===0)o=[255,255,255];else if(id>8)o=Math.abs(dy)<2.6?col:[255,255,255];else o=col;
  if(id===8&&r<1.6)o=[255,255,255];if(id>0&&id<8&&dx===-2&&dy===-2)o=[255,255,255];
  d[k]=o[0];d[k+1]=o[1];d[k+2]=o[2];d[k+3]=255}
 x.putImageData(im,0,0);return SPRITES[id]=c}
function rack(){const b=[{id:0,x:100,y:272,vx:0,vy:0,in:false}];const rows=[[1],[9,2],[3,8,10],[11,4,12,5],[13,6,14,15,7]],dx=2*PT.r+.3,dy=PT.r*Math.sqrt(3)+.3;
 rows.forEach((row,ri)=>row.forEach((id,ci)=>b.push({id,x:100+(ci-(row.length-1)/2)*dx,y:110-ri*dy,vx:0,vy:0,in:false})));return b}
const cloneB=bs=>bs.map(b=>({id:b.id,x:b.x,y:b.y,vx:0,vy:0,in:b.in}));
// one physics step: move, roll friction, pockets, cushions, ball–ball (equal masses, nearly elastic)
function poolStep(B,dt,ev){const {x0,y0,x1,y1,r}=PT;
 for(const b of B){if(b.in)continue;b.x+=b.vx*dt;b.y+=b.vy*dt;const sp=Math.hypot(b.vx,b.vy);
  if(sp>0){const ns=Math.max(0,sp-55*dt)*(1-.32*dt);if(ns<2.5){b.vx=b.vy=0}else{b.vx*=ns/sp;b.vy*=ns/sp}}
  let near=false;for(const [px,py] of POCKETS){const dd=Math.hypot(b.x-px,b.y-py);if(dd<10.5){b.in=true;b.vx=b.vy=0;ev.pocketed.push(b.id);break}if(dd<18)near=true}
  if(b.in)continue;
  if(!near){if(b.x<x0+r){b.x=x0+r;b.vx=Math.abs(b.vx)*.8}if(b.x>x1-r){b.x=x1-r;b.vx=-Math.abs(b.vx)*.8}if(b.y<y0+r){b.y=y0+r;b.vy=Math.abs(b.vy)*.8}if(b.y>y1-r){b.y=y1-r;b.vy=-Math.abs(b.vy)*.8}}
  else if(b.x<x0-6||b.x>x1+6||b.y<y0-6||b.y>y1+6){b.in=true;b.vx=b.vy=0;ev.pocketed.push(b.id)}}
 for(let i=0;i<B.length;i++){const a=B[i];if(a.in)continue;for(let j=i+1;j<B.length;j++){const c=B[j];if(c.in)continue;
  let dx=c.x-a.x,dy=c.y-a.y;const dd=Math.hypot(dx,dy);if(dd>=2*r||dd===0)continue;dx/=dd;dy/=dd;
  const ov=(2*r-dd)/2;a.x-=dx*ov;a.y-=dy*ov;c.x+=dx*ov;c.y+=dy*ov;
  const vr=(a.vx-c.vx)*dx+(a.vy-c.vy)*dy;if(vr>0){const imp=vr*.97;a.vx-=dx*imp;a.vy-=dy*imp;c.vx+=dx*imp;c.vy+=dy*imp;
   if(ev.first==null&&(a.id===0||c.id===0))ev.first=a.id===0?c.id:a.id}}}}
const moving=B=>B.some(b=>!b.in&&(b.vx||b.vy));
const SUB=4,PDT=1/240;
function shoot(B,shot){const c=B.find(b=>b.id===0);const v=60+shot.p*680;c.vx=shot.dx*v;c.vy=shot.dy*v}
function simulate(B0,shot){const B=cloneB(B0),ev={pocketed:[],first:null};shoot(B,shot);let n=0;while(moving(B)&&n<240*25){poolStep(B,PDT,ev);n++}for(const b of B){b.vx=b.vy=0}return{B,ev}}
const groupOf=id=>id===0||id===8?null:id<8?'hele':'halve';
const left=(B,g)=>B.filter(b=>!b.in&&groupOf(b.id)===g).length;
const tableCv=document.createElement('canvas');tableCv.width=PT.W;tableCv.height=PT.H;let tableFrame=-1;
function drawTable(){if(tableFrame===FRAME)return tableCv;tableFrame=FRAME;const c=tableCv.getContext('2d'),p=pen(c,21);c.fillStyle='#fff';c.fillRect(0,0,PT.W,PT.H);
 p.line([[6,6],[194,6],[194,350],[6,350]],'#111',2,.9,true);p.line([[PT.x0,PT.y0],[PT.x1,PT.y0],[PT.x1,PT.y1],[PT.x0,PT.y1]],'#111',1.3,.7,true);
 for(const [x,y] of POCKETS)p.shape(ell(x,y,8.5,8.5,14),'#111','#111',1,.5);
 for(let x=26;x<176;x+=9)p.line([[x,272],[x+4,272]],'#111',1,.3);p.dot(100,110,1.4,'#e0302a');
 for(const y of [70,110,150,210,250,290])for(const x of [11,189])p.dot(x,y,1,'#111');
 ink3(c,PT.W,PT.H);return tableCv}
function px(c,x,y,col,s=1){c.fillStyle=col;c.fillRect(Math.round(x),Math.round(y),s,s)}
function drawPool(c,st,aim){c.imageSmoothingEnabled=false;c.drawImage(drawTable(),0,0);
 for(const b of st.balls)if(!b.in)c.drawImage(sprite(b.id),Math.round(b.x-6),Math.round(b.y-6));
 if(aim&&aim.p>0){const cue=st.balls.find(b=>b.id===0),{dx,dy}=aim;
  // where does the line first touch a ball or a cushion?
  let tHit=Infinity,hit=null;for(const b of st.balls){if(b.in||b.id===0)continue;const ox=b.x-cue.x,oy=b.y-cue.y,pr=ox*dx+oy*dy;if(pr<=0)continue;const q=ox*ox+oy*oy-pr*pr,rr=4*PT.r*PT.r;if(q>rr)continue;const t=pr-Math.sqrt(rr-q);if(t<tHit){tHit=t;hit=b}}
  const tx=dx>0?(PT.x1-PT.r-cue.x)/dx:dx<0?(PT.x0+PT.r-cue.x)/dx:Infinity,ty=dy>0?(PT.y1-PT.r-cue.y)/dy:dy<0?(PT.y0+PT.r-cue.y)/dy:Infinity,tw=Math.min(tx,ty);
  const L=Math.min(tHit,tw);for(let t=9;t<L;t+=4)px(c,cue.x+dx*t,cue.y+dy*t,'#111');
  if(hit){const gx=cue.x+dx*L,gy=cue.y+dy*L;for(let a=0;a<6.28;a+=.35)px(c,gx+Math.cos(a)*6,gy+Math.sin(a)*6,'#111');let ux=hit.x-gx,uy=hit.y-gy;const u=Math.hypot(ux,uy);ux/=u;uy/=u;for(let t=8;t<36;t+=3)px(c,hit.x+ux*t,hit.y+uy*t,'#e0302a')}
  const back=10+aim.p*30;for(let t=back;t<back+95;t+=1){const col=t<back+6?'#111':((t|0)%14<7?'#8b5a2b':'#6b4420');px(c,cue.x-dx*t-.5,cue.y-dy*t-.5,col,2)}}}


/* ================================================================ chat integration (real friends, real turns) */
const $=s=>document.querySelector(s);
const C=()=>window.filmmaandChat;
let LIST={messages:[],pollId:null,canSend:false};
const games=()=>(LIST.messages||[]).filter(m=>m.kind==='game');
const pollKey=()=>LIST.pollId||'filmmaand';
const hopSeed=()=>hashStr('hop2:'+pollKey());   // v2 course; v1 used 'hop:' (its runs still replay, on their own seed)
const hopGid=()=>'hop-'+hashStr('gid:'+pollKey()).toString(36).padStart(7,'0');
const NAMECOL=['#e542a3','#1f7aec','#35cd96','#fc9775','#029d00','#d3a91d','#a62c71','#ff8f2c','#b04632','#6bcbef'];
const nameCol=n=>{let h=0;for(const ch of String(n))h=(h*31+ch.charCodeAt(0))>>>0;return NAMECOL[h%NAMECOL.length]};
const toastEl=document.createElement('div');toastEl.className='gm-toast';toastEl.hidden=true;document.body.append(toastEl);let toastT=0;
function toast(t,ms=2200){toastEl.textContent=t;toastEl.hidden=false;clearTimeout(toastT);toastT=setTimeout(()=>toastEl.hidden=true,ms)}
let sentAt=0;const REDUCED=matchMedia('(prefers-reduced-motion: reduce)');
const newKey=()=>'game-'+Array.from(crypto.getRandomValues(new Uint8Array(10)),b=>b.toString(16).padStart(2,'0')).join('');
async function send(game,gid,payload){const chat=C();if(!chat||typeof chat.sendGame!=='function'){toast('Spelletjes werken hier nog niet.');return false}
 try{await chat.sendGame({game,gid,payload},{key:newKey()});sentAt=Date.now();return true}
 catch(e){toast(e&&e.code==='game_rate'?'Even rustig aan, probeer het zo nog eens.':e&&e.code==='game_too_big'?'Die run is te lang om te versturen.':e&&e.code==='date_poll_closed'?'De chat is gesloten.':'Versturen lukte niet. Probeer het zo nog eens.');return false}}

/* ---- Hop: runs are delta-encoded press/release frames; every client re-simulates them (ghosts + honest scores) */
const enc=a=>a.map((f,i)=>i?f-a[i-1]:f),dec=a=>{let s=0;return a.map(d=>s+=d)};
const VERIFY=new Map();
// the score shown is always the one this phone re-simulates, never the one the sender claims (a mismatch shows '?')
const hopVer=m=>m.payload&&m.payload.v===2?2:1;
function verified(m){if(VERIFY.has(m.id))return VERIFY.get(m.id);const P=m.payload||{},ver=hopVer(m),seed=P.seed>>>0;let frames=[],score=0,ok=true;
 try{frames=dec(Array.isArray(P.frames)?P.frames.slice(0,4000).map(n=>n|0):[]);
  if(ver===2&&HR){if(frames.some(f=>f<0||f>HR.MAXF+1))throw 0;score=HR.replay(seed,frames).score}
  else if(ver===2)ok=false;
  else{const s=hopRun(seed,frames);while(!s.dead)hopStep(s,ghostHeld(s));score=s.score}}catch{ok=false}
 const v={name:m.name||'?',self:!!m.self,score,frames,seed,ver,ok,claimed:P.score,match:ok&&P.score===score};VERIFY.set(m.id,v);return v}
// ghosts and rankings: only runs on today's v2 course
function hopRuns(){return games().filter(m=>m.game==='hop'&&m.payload&&hopVer(m)===2&&(m.payload.seed>>>0)===hopSeed()).map(verified).filter(r=>r.ok)}
function bestPer(){const by=new Map();for(const r of hopRuns()){const k=r.self?'\u0000me':r.name;const b=by.get(k);if(!b||r.score>b.score)by.set(k,r)}return by}
function ghostList(){const by=bestPer(),out=[];for(const [k,r] of by)if(k!=='\u0000me')out.push({name:r.name,score:r.score,frames:r.frames});
 out.sort((a,b)=>b.score-a.score);const g=out.slice(0,4);const mine=by.get('\u0000me');if(mine)g.push({name:'jouw beste',score:mine.score,frames:mine.frames});return g}

/* ---- Pool: the gid's messages, folded. Players = the first two distinct authors; the last turn's end state is the truth */
const toArr=B=>{const a=Array(16).fill(null);for(const b of B)if(!b.in)a[b.id]=[+b.x.toFixed(1),+b.y.toFixed(1)];return a};
const fromArr=a=>a.map((p,id)=>p?{id,x:p[0],y:p[1],vx:0,vy:0,in:false}:{id,x:-50,y:-50,vx:0,vy:0,in:true});
// The fold every client runs over the same seq-ordered messages, so every client lands on the same game (Capsule QA,
// 23 Sept: a third sender used to be accepted by some clients and fork the board). Rules, in seq order:
//  - the first well-formed message is the break: its sender is seat 0;
//  - after that a turn counts only if its sender is the seat the previous COUNTED turn handed the table to
//    (payload.turn). Seat 1 is taken by the first other sender who shoots when it is seat 1's go;
//  - anything else (a third person, someone out of turn, a double send, anything after the game is over) is ignored.
// A valid game played before this fold is unchanged by it: its turns already alternate between two people.
const poolKey=m=>m.self?'\u0000me':'n:'+(m.name||'?');
const poolOk=P=>!!P&&Array.isArray(P.end)&&Array.isArray(P.groups)&&(P.turn===0||P.turn===1)&&(P.over===null||P.over===0||P.over===1)&&Array.isArray(P.shots);
function foldPool(messages,gid){const all=(messages||[]).filter(m=>m.kind==='game'&&m.game==='pool'&&m.gid===gid&&poolOk(m.payload))
  .sort((a,b)=>(a.seq||0)-(b.seq||0)||String(a.id).localeCompare(String(b.id)));
 const seats=[],turns=[],ignored=[];let last=null;
 for(const m of all){const k=poolKey(m);
  if(!last){seats.push({key:k,name:m.self?'jij':(m.name||'?'),self:!!m.self});turns.push(m);last=m;continue}
  const P=last.payload,want=P.turn;
  if(P.over!==null){ignored.push(m);continue}
  if(seats.length<2){if(want===1&&k!==seats[0].key){seats.push({key:k,name:m.self?'jij':(m.name||'?'),self:!!m.self});turns.push(m);last=m}
   else if(want===0&&k===seats[0].key){turns.push(m);last=m}else ignored.push(m);continue}
  if(seats[want].key===k){turns.push(m);last=m}else ignored.push(m)}
 return last?{turns,ignored,seats,last}:null}
const seatNames=g=>g.players.map(p=>p.self?'jij':p.name).join(' en ');
function poolGame(gid,messages){const F=foldPool(messages||(LIST.messages||[]),gid);if(!F)return null;
 const players=F.seats,last=F.last,P=last.payload;let me=players.findIndex(p=>p.self);if(me<0&&players.length<2)me=1;
 const full=players.length>=2&&me<0;          // two others already play: you can only watch
 const opp=me<0?null:players[1-me]||null;
 return {gid,turns:F.turns,ignored:F.ignored,players,me,full,opp,last,balls:fromArr(P.end),turn:P.turn,groups:P.groups.slice(),over:P.over,myTurn:me>=0&&P.over===null&&P.turn===me,lastBySomeoneElse:!last.self}}
function judge(st,B,ev,who){const other=1-who,pk=ev.pocketed.filter(id=>id!==0),scratch=ev.pocketed.includes(0);let over=null,cont=false,note='';
 if(pk.includes(8)){const g=st.groups[who];over=(g&&left(B,g)===0&&!scratch)?who:other;note=over===who?'de 8 erin!':'de 8 te vroeg…'}
 else{if(!st.groups[who]){const f=pk.find(id=>id!==8);if(f){st.groups[who]=groupOf(f);st.groups[other]=groupOf(f)==='hele'?'halve':'hele'}}
  const g=st.groups[who],mine=pk.filter(id=>g?groupOf(id)===g:true);cont=!scratch&&mine.length>0;note=scratch?'wit erin (fout)':pk.length?pk.length+' gepot':'mis'}
 if(scratch&&over===null){const c=B.find(b=>b.id===0);c.in=false;c.x=100;c.y=272;for(let k=0;k<30&&B.some(b=>b!==c&&!b.in&&Math.hypot(b.x-c.x,b.y-c.y)<2*PT.r+1);k++)c.x=100+((k%2)?1:-1)*(k+1)*4}
 st.balls=B;st.over=over;st.turn=over!==null?other:cont?who:other;return {note,cont,over,pk,scratch}}

/* ---- game messages (eggs.js calls makeCard for kind 'game'). Chris: "the message shouldn't look special, all should look really
   native". So: an ordinary chat bubble (same classes as text, so runs group the same way), a rounded picture, a bold "Biljart?",
   one grey line. Tap anywhere on it to play. The picture is drawn once from that message's own payload. */
const CARDS=new Map(),TW=220,TH=130,TITLE={hop:'Pudding Hop?',pool:'Biljart?'};
const clockOf=at=>{try{return new Intl.DateTimeFormat('nl-NL',{timeZone:'Europe/Amsterdam',hour:'2-digit',minute:'2-digit'}).format(new Date(at))}catch{return ''}};
function makeCard(m){const el=document.createElement('div');el.className='msg eg-cm gm-msg '+(m.self?'out':'in');el.setAttribute('role','button');el.tabIndex=0;
 if(!m.self){if(m.avatar){const a=document.createElement('img');a.className='eg-av';a.alt='';a.src=m.avatar;el.append(a)}const f=document.createElement('div');f.className='from';f.textContent=m.name||'?';f.style.color=nameCol(m.name||'?');el.append(f)}
 const cv=document.createElement('canvas');cv.className='gm-th';cv.width=TW;cv.height=TH;cv.setAttribute('aria-hidden','true');
 const bd=document.createElement('div');bd.className='gm-bd';const ti=document.createElement('b');ti.className='gm-ti';ti.textContent=TITLE[m.game]||'Spel?';
 const sub=document.createElement('span');sub.className='gm-sub';const t=document.createElement('span');t.className='t';t.textContent=m.t||clockOf(m.at);
 if(m.self){const k=document.createElement('b');k.textContent='✓✓';t.append(' ',k)}
 bd.append(ti,sub,t);el.append(cv,bd);
 const cd={el,cv,sub,m};CARDS.set(m.id,cd);
 const go=()=>open(cd);el.addEventListener('click',go);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go()}});
 el._play=()=>el.classList.add('pop2');
 if(m.self&&Date.now()-sentAt<8000){sentAt=0;requestAnimationFrame(()=>el.isConnected&&el.scrollIntoView({block:'end',behavior:REDUCED.matches?'auto':'smooth'}))}
 subtitle(cd);thumb(cv,m);return el}
function subtitle(cd){const m=cd.m;let s='';
 if(m.game==='hop'){const v=verified(m),sc=v.ok?String(v.score)+(v.ver===2&&!v.match?' (?)':''):'?';   // v1 was float physics: never flag it
  s=v.ver===1?(m.self?'Jouw run: ':(m.name||'?')+': ')+sc+' · oude baan'
   :m.self?'Jouw run: '+sc:(m.name||'?')+': '+sc+' · verslaan?'}
 else{const g=poolGame(m.gid);
  s=!g?'':g.over!==null?(g.players[g.over]?(g.players[g.over].self?'Jij hebt gewonnen':g.players[g.over].name+' heeft gewonnen'):'Afgelopen')
   :g.full?seatNames(g)+' spelen al':g.players.length<2&&g.me===0?'Wacht op een tegenspeler':g.myTurn?'Jouw beurt':'Beurt van '+((g.players[g.turn]||{}).name||'de ander')}
 cd.sub.textContent=s;cd.el.setAttribute('aria-label',(TITLE[m.game]||'Spel?')+' '+s)}
// the pictures: notebook ink on paper, still (no boil in the chat)
function thumb(cv,m){const c=cv.getContext('2d',{willReadFrequently:true}),f=FRAME;FRAME=0;
 try{c.setTransform(1,0,0,1,0,0);c.fillStyle='#fff';c.fillRect(0,0,TW,TH);if(m.game==='hop')thumbHop(c,m);else thumbPool(c,m)}finally{FRAME=f}}
// notebook paper, a shade off white, so the picture keeps its edge inside a white bubble
function paper(c){const im=c.getImageData(0,0,TW,TH),d=im.data;for(let i=0;i<d.length;i+=4)if(d[i]===255&&d[i+1]===255&&d[i+2]===255){d[i]=248;d[i+1]=246;d[i+2]=240}c.putImageData(im,0,0)}
function thumbHop(c,m){const G=110,p=pen(c,hashStr('th:'+(m.id||'hop')));
 p.line([[-4,G],[80,G+.6],[150,G],[226,G+.6]],'#111',1.5,.7);
 for(let i=0;i<8;i++){const x=10+i*28+p.j(8);p.line([[x,G+8],[x+7+p.j(4),G+8]],'#111',1.1,.3)}
 c.setTransform(1,0,0,1,0,G-HOP.G);drawObs(pen(c,5),{k:'reel',w:32,h:32,x:40,id:3},117);c.setTransform(1,0,0,1,0,0);
 cat(pen(c,9),133,G-44,.66,{rot:-.16});                                   // the pudding, mid-hop over the reel
 for(const [y,x,l] of [[G-78,76,18],[G-66,70,24],[G-54,80,14]])p.line([[x,y],[x+l,y]],'#111',1.3,.4);   // speed lines
 ink3(c,TW,TH);paper(c)}
function thumbPool(c,m){const p=pen(c,hashStr('th:'+(m.id||'pool'))),x0=8,y0=8,x1=212,y1=122,cx=(x0+x1)/2;
 p.line([[x0,y0],[x1,y0],[x1,y1],[x0,y1]],'#111',1.8,.6,true);
 p.line([[x0+7,y0+7],[x1-7,y0+7],[x1-7,y1-7],[x0+7,y1-7]],'#111',1,.4,true);
 for(const [x,y] of [[x0+7,y0+7],[cx,y0+5],[x1-7,y0+7],[x0+7,y1-7],[cx,y1-5],[x1-7,y1-7]])p.dot(x,y,4.6,'#111');
 const hs=x0+7+(PT.y1-272)/(PT.y1-PT.y0)*(x1-x0-14);for(let y=y0+14;y<y1-12;y+=7)p.line([[hs,y],[hs,y+3]],'#111',1,.2);   // head string
 ink3(c,TW,TH);paper(c);
 // balls in colour on top: the table's long side runs left to right, the rack on the right
 const sx=(x1-x0-14)/(PT.y1-PT.y0),sy=(y1-y0-14)/(PT.x1-PT.x0),R=Math.max(3.4,PT.r*Math.min(sx,sy));
 c.lineWidth=1;(m.payload.end||[]).forEach((b,id)=>{if(!b)return;const X=x1-7-(b[1]-PT.y0)*sx,Y=y0+7+(b[0]-PT.x0)*sy,col=BALLCOL[id];
  c.save();c.beginPath();c.arc(X,Y,R,0,7);c.fillStyle=id>8||id===0?'#fff':col;c.fill();
  if(id>8){c.clip();c.fillStyle=col;c.fillRect(X-R,Y-R*.45,2*R,R*.9)}c.restore();
  c.beginPath();c.arc(X,Y,R,0,7);c.strokeStyle='#111';c.stroke()})}
function refreshAll(){for(const cd of CARDS.values()){if(!cd.el.isConnected){CARDS.delete(cd.m.id);continue}subtitle(cd)}}
setInterval(()=>{if(!still)FRAME++;if(OV&&OV.tick12)OV.tick12()},83);

/* ---- the game drawer: a sheet that slides up over the chat (the chat stays visible, dimmed, behind it), like a game
   opened from a message in any phone chat. Close: ×, Escape, tapping the dimmed chat, or swiping the handle down. */
const dim=document.createElement('div');dim.className='gm-dim';dim.hidden=true;
const ov=document.createElement('div');ov.className='gm-ov';ov.hidden=true;ov.setAttribute('role','dialog');ov.setAttribute('aria-modal','true');
ov.innerHTML='<div class="gm-grab" aria-hidden="true"><span></span></div><div class="gm-head"><div class="gm-hd"><b class="gm-ovt"></b><small class="gm-ovs"></small></div>'+
 '<button class="gm-x" aria-label="Sluiten"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M19 6.4 17.6 5 12 10.6 6.4 5 5 6.4 10.6 12 5 17.6 6.4 19 12 13.4 17.6 19 19 17.6 13.4 12z"/></svg></button></div><div class="gm-stage"></div>';
document.body.append(dim,ov);const stage=ov.querySelector('.gm-stage');let OV=null,closing=0;
ov.setAttribute('aria-labelledby','gm-ovt');ov.querySelector('.gm-ovt').id='gm-ovt';
// desktop: the drawer covers the chat pane only (the composer bar spans exactly that pane)
function place(){const f=document.querySelector('.foot'),r=f&&innerWidth>=900?f.getBoundingClientRect():null,on=!!(r&&r.width);
 Object.assign(ov.style,on?{left:r.left+'px',width:r.width+'px'}:{left:'',width:''});dim.style.left=on?r.left+'px':''}
function openOv(title,sub,mod){if(OV)closeOv(true);clearTimeout(closing);ov.querySelector('.gm-ovt').textContent=title;ov.querySelector('.gm-ovs').textContent=sub||'';
 stage.replaceChildren();place();ov.style.transform='';ov.hidden=dim.hidden=false;OV=mod;mod.mount(stage);
 const on=()=>{ov.classList.add('on');dim.classList.add('on')};if(still)on();else{void ov.offsetHeight;requestAnimationFrame(on)}
 ov.querySelector('.gm-x').focus({preventScroll:true})}
// after a game closes: one re-read, so a waiting player sees the other's move soon (the page throttles it)
function closeOv(now){if(!OV&&ov.hidden)return;if(OV&&OV.unmount)OV.unmount();OV=null;ov.classList.remove('on','drag');dim.classList.remove('on');ov.style.transform='';
 const done=()=>{if(OV)return;ov.hidden=dim.hidden=true;stage.replaceChildren()};clearTimeout(closing);if(now===true||still)done();else closing=setTimeout(done,280);
 const chat=C();if(chat&&typeof chat.refresh==='function')try{chat.refresh()}catch{}}
dim.addEventListener('click',()=>closeOv());ov.querySelector('.gm-x').addEventListener('click',()=>closeOv());
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&OV)closeOv()});
{let y0=null,dy=0;for(const h of [ov.querySelector('.gm-grab'),ov.querySelector('.gm-head')]){
 h.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;y0=e.clientY;dy=0;try{h.setPointerCapture(e.pointerId)}catch{}ov.classList.add('drag')});
 h.addEventListener('pointermove',e=>{if(y0===null)return;dy=Math.max(0,e.clientY-y0);ov.style.transform='translateY('+dy+'px)'});
 const up=()=>{if(y0===null)return;y0=null;ov.classList.remove('drag');if(dy>80)closeOv();else ov.style.transform=''};
 h.addEventListener('pointerup',up);h.addEventListener('pointercancel',up)}}
// a game canvas as big as the drawer allows, keeping its pixels square
function fitCanvas(cv,W,H,reserve){const k=Math.max(.6,Math.min((stage.clientWidth-24)/W,(stage.clientHeight-reserve)/H));cv.style.width=Math.floor(W*k)+'px';cv.style.height=Math.floor(H*k)+'px'}
function open(cd){const m=cd.m;if(m.game==='hop'){openOv('Pudding Hop','Dezelfde baan voor iedereen',hopModule());return}
 const g=poolGame(m.gid);if(!g)return;if(g.over!==null){challenge();return}
 if(!g.myTurn&&!(g.lastBySomeoneElse&&g.last.id===m.id)){toast(g.full?seatNames(g)+' spelen al':'Beurt van '+((g.players[g.turn]||{}).name||'de ander'));return}
 openOv('Biljart',g.full?seatNames(g):g.opp?'Tegen '+g.opp.name:'',poolModule(g))}
// the freshest chat list we can get (a refresh if the chat offers one, briefly awaited), then the fold again
async function freshPool(gid){const chat=C();try{const r=chat&&typeof chat.refresh==='function'&&chat.refresh();if(r&&typeof r.then==='function')await Promise.race([r.catch(()=>{}),new Promise(z=>setTimeout(z,1500))])}catch{}
 try{const L=chat&&typeof chat.list==='function'&&chat.list();if(L&&Array.isArray(L.messages))LIST=Object.assign({},LIST,L)}catch{}return poolGame(gid)}
// may I still send this turn? (my seat, my go, and nobody moved since the state I played from)
function stillMine(g,g2,me){if(g.fresh)return g2?{ok:false,why:'Dat spel bestaat al.'}:{ok:true};
 if(!g2)return{ok:false,why:'Dat spel is niet meer te vinden.'};
 if(g2.full||g2.me!==me)return{ok:false,why:(g2.full?seatNames(g2)+' spelen al.':'Iemand anders speelt al.')+' Je beurt is niet verstuurd.'};
 if(!g2.myTurn||g2.last.id!==g.last.id)return{ok:false,why:'Er is net een andere beurt bijgekomen. Je beurt is niet verstuurd.'};return{ok:true}}

/* ---- Hop module: today's course (the same for everyone in this poll), your friends' best runs as ghosts */
function hopModule(){const SEED=hopSeed(),DT=1/60;let fit,cv,cx,panel,hint,sim,ghosts,rec,held,phase,raf=0,acc=0,last=0,deadAt=0,flash=null,passed,next='',take=0,R=null;
 // v2 (games/hop-rules.js): the sim is integer-only and one step per 60 Hz frame; the renderer only reads it
 function reset(){sim=HR.newRun(SEED);rec=[];held=false;phase='ready';passed=new Set();flash=null;take++;
  ghosts=ghostList().map(g=>({name:g.name,score:g.score,run:HR.newRun(SEED,g.frames)}));panel.hidden=true;
  hint.textContent=ghosts.length?'Je racet tegen: '+ghosts.map(g=>g.name+' '+g.score).join(' · '):'Zet de eerste score neer. Het wordt snel. Heel snel.'}
 function start(){phase='run';last=performance.now();acc=0}
 function press(){if(phase==='ready'){start();return}if(phase==='dead'){if(performance.now()-deadAt>380){reset();start()}return}if(!held){held=true;rec.push(sim.f)}}
 function release(){if(held){held=false;if(phase==='run')rec.push(sim.f)}}
 function die(){phase='dead';deadAt=performance.now();if(held){rec.push(sim.f);held=false}if(rec.length%2)rec.push(sim.f);
  const all=[{name:'jij',score:sim.score,me:true},...ghosts.filter(g=>g.name!=='jouw beste').map(g=>({name:g.name,score:g.score}))].sort((a,b)=>b.score-a.score),rank=all.findIndex(x=>x.me)+1;
  setTimeout(()=>{if(phase!=='dead')return;panel.hidden=false;const r=panel.querySelector('.gm-rank');r.replaceChildren();
   all.forEach((x,i)=>{const d=document.createElement('div');d.textContent=(i+1)+'. '+x.name+' · '+x.score;if(x.me)d.className='me';r.append(d)});
   hint.textContent=(sim.end?'EINDE gehaald! ':'')+'#'+rank+' van '+all.length+(rank===1&&all.length>1?' · jij staat bovenaan':'')},380)}
 function frame(ts){raf=requestAnimationFrame(frame);
  if(phase==='run'){acc+=Math.min(.1,(ts-last)/1000);last=ts;
   while(acc>=DT){acc-=DT;HR.step(sim,held);for(const g of ghosts)HR.step(g.run,HR.heldAt(g.run));
    for(const g of ghosts){if(g.run.dead&&!passed.has(g.name)&&sim.score>g.run.score){passed.add(g.name);flash={t:g.name+' ingehaald!',n:70}}}
    if(sim.dead){die();break}}}
  const up=ghosts.filter(g=>g.score>sim.score).sort((a,b)=>a.score-b.score)[0];next=up?'volgende: '+up.name+' '+up.score:(ghosts.length?'je staat vooraan':'');
  R.draw(cx,{player:sim,ghosts,phase,flash,next,take,deadAge:phase==='dead'?performance.now()-deadAt:0,showRetry:phase==='dead'&&performance.now()-deadAt>380})}
 // what goes on the wire: only the presses that made a jump. Checked here too: if compaction ever changed the run, send it raw.
 function payload(){const raw=rec.slice(),c=HR.compact(SEED,raw),r=HR.replay(SEED,c),use=r.score===sim.score&&r.f===sim.f?c:raw;
  return{v:2,seed:SEED,frames:enc(use),score:sim.score}}
 const kd=e=>{if(e.code==='Space'||e.code==='ArrowUp'||e.code==='KeyW'){e.preventDefault();if(!e.repeat)press()}},ku=e=>{if(e.code==='Space'||e.code==='ArrowUp'||e.code==='KeyW')release()};
 return {mount(st){R=HR.makeRenderer({pen,cat,ell,frame:()=>FRAME,still:()=>still});
   const pap=document.createElement('div');pap.className='gm-paper';cv=document.createElement('canvas');cv.className='gm-hopc gm-cv';cv.width=R.W;cv.height=R.H;pap.append(cv);cx=cv.getContext('2d',{willReadFrequently:true});
   hint=document.createElement('p');hint.className='gm-hint';panel=document.createElement('div');panel.className='gm-panel';
   panel.innerHTML='<div class="gm-rank"></div><div class="gm-row"><button class="gm-btn gm-send">Stuur je run</button><button class="gm-btn gm-ghost">Opnieuw</button></div>';
   st.append(pap,hint,panel);
   st.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;e.preventDefault();press()});st.addEventListener('pointerup',release);st.addEventListener('pointercancel',release);st.addEventListener('pointerleave',release);
   addEventListener('keydown',kd);addEventListener('keyup',ku);
   panel.querySelector('.gm-ghost').onclick=()=>{reset();start()};
   panel.querySelector('.gm-send').onclick=async e=>{const b=e.currentTarget;b.disabled=true;const ok=await send('hop',hopGid(),payload());b.disabled=false;if(ok)closeOv()};
   fit=()=>fitCanvas(cv,R.W,R.H,190);fit();addEventListener('resize',fit);
   reset();raf=requestAnimationFrame(frame)},
  unmount(){cancelAnimationFrame(raf);removeEventListener('keydown',kd);removeEventListener('keyup',ku);removeEventListener('resize',fit)},
  test:{press,release,payload,sim:()=>sim,state:()=>({phase,score:sim.score,f:sim.f,dead:sim.dead,end:sim.end,cause:sim.cause,ghosts:ghosts.map(g=>[g.name,g.run.score,g.run.dead])})}}}

/* ---- Pool module: replay the other player's last turn, then (if it's yours) aim and shoot; one message per turn */
function poolModule(g){const st={balls:cloneB(g.balls),groups:g.groups.slice(),turn:g.turn,over:g.over};let fit;
 const spectator=g.me<0;let me=spectator?-1:g.me;let cv,cx,hint,raf=0,phase='idle',aim=null,drag=null,anim=null,turnShots=[],turnStart=null,notes=[];
 const oppName=()=>(g.opp&&g.opp.name)||'de ander';
 let lockMsg='';const status=()=>{if(lockMsg){hint.textContent=lockMsg;return}if(spectator){hint.textContent=seatNames(g)+' spelen al · je kijkt mee';return}const mine=st.groups[me];hint.textContent=st.over!==null?(st.over===me?'Jij wint! 🎱':oppName()+' wint 🎱'):st.turn===me?'Jij'+(mine?' ('+mine+')':'')+': sleep naar achteren om te mikken, loslaten = stoot':oppName()+' is aan de beurt'};
 const render=()=>drawPool(cx,st,phase==='aim'&&aim?aim:null);
 function toCanvas(e){const r=cv.getBoundingClientRect();return [(e.clientX-r.left)/r.width*PT.W,(e.clientY-r.top)/r.height*PT.H]}
 function animate(shot,done){anim={B:cloneB(st.balls),ev:{pocketed:[],first:null}};shoot(anim.B,shot);const vis={...st,balls:anim.B};
  const tick=()=>{for(let k=0;k<SUB;k++)poolStep(anim.B,PDT,anim.ev);drawPool(cx,vis,null);if(moving(anim.B))raf=requestAnimationFrame(tick);else{for(const b of anim.B)b.vx=b.vy=0;const a=anim;anim=null;done(a)}};raf=requestAnimationFrame(tick)}
 async function endTurn(){phase='sending';hint.textContent='versturen…';
  const chk=stillMine(g,await freshPool(g.gid),me);if(!chk.ok){phase='idle';hint.textContent=chk.why;toast(chk.why,3200);setTimeout(()=>{if(OV)closeOv()},2600);return}
  const payload={shots:turnShots,start:toArr(turnStart),end:toArr(st.balls),turn:st.turn,groups:st.groups.slice(),over:st.over};
  send('pool',g.gid,payload).then(ok=>{if(ok)setTimeout(closeOv,500);else{phase='idle';status()}})}
 // a turn starts from the wire state (1 decimal), so the other side replays it exactly: a racked break is chaotic, a 0.05 nudge changes everything
 function myShot(shot){if(!turnStart){st.balls=fromArr(toArr(st.balls));turnStart=cloneB(st.balls)}turnShots.push(shot);phase='anim';hint.textContent='…';
  animate(shot,({B,ev})=>{const res=judge(st,B,ev,me);notes.push(res.note);render();status();
   if(st.turn===me&&st.over===null&&turnShots.length<8){phase='aim';if(res.pk.length)toast(res.note+' · nog een keer!');return}
   if(st.turn===me&&st.over===null)st.turn=1-me;// at most 8 shots per turn: then it's the other's go
   endTurn()})}
 function replay(done){const P=g.last.payload;st.balls=fromArr(P.start);render();hint.textContent=(g.last.name||'de ander')+' stoot…';let i=0;
  const nextShot=()=>{if(i>=P.shots.length){st.balls=fromArr(P.end);st.groups=P.groups.slice();st.turn=P.turn;st.over=P.over;render();done();return}
   animate(P.shots[i++],({B})=>{st.balls=B;render();setTimeout(nextShot,450)})};setTimeout(nextShot,500)}
 return {mount(el){const pap=document.createElement('div');pap.className='gm-paper';cv=document.createElement('canvas');cv.className='gm-poolc gm-cv';cv.width=PT.W;cv.height=PT.H;pap.append(cv);cx=cv.getContext('2d');hint=document.createElement('p');hint.className='gm-hint';el.append(pap,hint);fit=()=>fitCanvas(cv,PT.W,PT.H,64);fit();addEventListener('resize',fit);
   cv.addEventListener('pointerdown',e=>{if(phase!=='aim')return;e.preventDefault();try{cv.setPointerCapture(e.pointerId)}catch{}drag=toCanvas(e);aim=null});
   cv.addEventListener('pointermove',e=>{if(!drag||phase!=='aim')return;const [x,y]=toCanvas(e);let dx=drag[0]-x,dy=drag[1]-y;const L=Math.hypot(dx,dy);if(L<3){aim=null;render();return}aim={dx:dx/L,dy:dy/L,p:Math.min(1,L/110)};render();hint.textContent='kracht '+Math.round(aim.p*100)+'%'});
   const up=()=>{if(!drag)return;drag=null;if(phase==='aim'&&aim&&aim.p>.04){const s={dx:+aim.dx.toFixed(4),dy:+aim.dy.toFixed(4),p:+aim.p.toFixed(3)};aim=null;myShot(s)}else{aim=null;render();status()}};
   cv.addEventListener('pointerup',up);cv.addEventListener('pointercancel',up);
   render();const go=()=>{phase=!spectator&&st.over===null&&st.turn===me?'aim':'idle';status();render()};
   if(g.lastBySomeoneElse&&g.last.payload.shots.length&&!g.fresh){phase='replay';replay(go)}else go();
   // someone may have taken the seat since this list was read: check now, before you line up a shot for nothing
   if(!spectator&&!g.fresh)freshPool(g.gid).then(g2=>{const chk=stillMine(g,g2,me);if(!chk.ok&&!turnShots.length&&(phase==='aim'||phase==='replay'||phase==='idle')){me=-1;lockMsg=chk.why.replace(' Je beurt is niet verstuurd.','')+' Je kijkt mee.';if(phase!=='replay')phase='idle';status();render()}})},
  unmount(){cancelAnimationFrame(raf);removeEventListener('resize',fit)},
  tick12(){if(phase==='aim'||phase==='idle')render()},
  test:{shoot:(dx,dy,p)=>{if(phase==='aim')myShot({dx,dy,p})},state:()=>({phase,turn:st.turn,me,over:st.over,groups:st.groups,inPlay:st.balls.filter(b=>!b.in).length})}}}
// a new challenge: you break; the first message carries your break, the friend who answers becomes player two
function challenge(){const gid='pool-'+newKey().slice(5,17);const B=rack();
 const g={gid,turns:[],players:[{key:'\u0000me',name:'jij',self:true}],me:0,opp:null,last:null,balls:B,turn:0,groups:[null,null],over:null,myTurn:true,lastBySomeoneElse:false,fresh:true};
 openOv('Biljart','Jij breekt',poolModule(g))}

